mkdir -p /tmp/an && cat > /tmp/an/bbox.py <<'EOF'
import subprocess,sys
def load(p):
    w,h=[int(x) for x in subprocess.check_output(['ffprobe','-v','error','-select_streams','v','-show_entries','stream=width,height','-of','csv=p=0',p]).decode().split(',')]
    raw=subprocess.check_output(['ffmpeg','-v','error','-i',p,'-f','rawvideo','-pix_fmt','rgba','-'])
    return w,h,raw
def bbox(w,raw,x0,y0,s):
    xs=[];ys=[]
    for y in range(y0,y0+s):
        for x in range(x0,x0+s):
            if raw[(y*w+x)*4+3]>0: xs.append(x-x0);ys.append(y-y0)
    return (min(xs),min(ys),max(xs),max(ys)) if xs else None
for p in sys.argv[1:]:
    w,h,raw=load(p)
    cols=w//32
    out=[]
    for i in range((w//32)*(h//32)):
        out.append(bbox(w,raw,(i%cols)*32,(i//cols)*32,32))
    print(p.split('Doors/')[1]); print('  ',out)
EOF
cd /app; python3 -I /tmp/an/bbox.py Resources/Textures/Structures/Doors/Airlocks/*/firelock-base.rsi/{closed,open}.png Resources/Textures/Structures/Doors/Airlocks/Effects/airlock-effects-firelock.rsi/{closed_unlit,pressure_unlit,temperature_unlit,bolted_unlit,welded}.png

